      <a (click)="filtrarPorTipo('Perro')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para perros</a>
    </li>

</ul>

<ul class="list-group list-group-flush">
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Gatos</li>

    <!--FILTROS PIENSOS GATOS-->
    <li class="list-group-item">
      <a (click)="filtrarPorTipo('Gato')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para gatos</a>
    </li>

</ul>

<br>

    <!--BOTONES DE PRECIO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;margin-left: 13px;">Precios</li>

    <!-- Input de Rango de Precios Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="precio1" name="grupo1" (click)="filtros.precio='0-10'; aplicarFiltros()">
      <label for="precio1"> 0 - 10</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio2" name="grupo1" (click)="filtros.precio='11-20'; aplicarFiltros()">
      <label for="precio1"> 11 - 20</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio3" name="grupo1" (click)="filtros.precio='21-30'; aplicarFiltros()">
      <label for="precio1"> 21 - 30</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio4" name="grupo1" (click)="filtros.precio='31-40'; aplicarFiltros()">
      <label for="precio1"> 31 - 40</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio5" name="grupo1" (click)="filtros.precio='41-50'; aplicarFiltros()">
      <label for="precio1"> 41 - 50</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio1" name="grupo1" (click)="filtros.precio='51-60'; aplicarFiltros()">
      <label for="precio1"> 51 - 60</label>
    </div>



    <!--BOTONES DE PESO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Peso</li>


    <!-- Input de Rango de Peso Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="peso1" name="grupo2" (click)="filtrarPorPeso('0-5')">
      <label class="form-check-label" for="Peso">0 - 5</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso2" name="grupo2" (click)="filtrarPorPeso('6-10')">
      <label class="form-check-label" for="Peso">6 - 10</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso3" name="grupo2" (click)="filtrarPorPeso('11-15')">
      <label class="form-check-label" for="Peso">11 - 15</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso4" name="grupo2" (click)="filtrarPorPeso('16-20')">
      <label class="form-check-label" for="Peso">16 - 20</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso5" name="grupo2" (click)="filtrarPorPeso('21-25')">
      <label class="form-check-label" for="Peso">21 - 25</label>
    </div>

    <br>

    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;margin-left: 13px;">Buscar por tipo de edad</li>


  <!--CHECKBOX DE JUNIOR, ADULTO Y SENIOR-->
  <div class="form-check">
    <input type="checkbox" id="edad1" name="grupo3" (click)="filtrarPorEdad('Junior')">
    <label class="form-check-label" for="Edad"  style="margin-left: 10px;">Junior</label>
  </div>

  <div class="form-check">
    <input type="checkbox" id="edad2" name="grupo3" (click)="filtrarPorEdad('Adulto')">
    <label class="form-check-label" for="Edad" style="margin-left: 10px;">Adulto</label>
  </div>

  <div class="form-check">
    <input type="checkbox" id="edad3" name="grupo3" (click)="filtrarPorEdad('Senior')">
    <label class="form-check-label" for="Edad"  style="margin-left: 10px;">Senior</label>
  </div>
